1|// Persisted music prefs: style, Chopin mode, volume, and muted. Storage
2|// can throw (private mode), so every access is guarded and falls back.
3|// Old values load safely: unknown fields are ignored, a missing or bad
4|// playlist, volume, or muted falls back to the defaults.
5|import type { PersistedMusicPrefs } from "@/core/music";
6|
7|export const MUSIC_PREFS_KEY = "lectoria.music.v1";
8|
9|export const DEFAULT_VOLUME = 0.8;
10|
11|type PrefsStorage = Pick<Storage, "getItem" | "setItem">;
12|
13|function validVolume(value: unknown): number | null {
14|  return typeof value === "number" && Number.isFinite(value) && value >= 0 && value <= 1
15|    ? value
16|    : null;
17|}
18|
19|function readStored(storage: PrefsStorage | undefined): PersistedMusicPrefs | null {
20|  try {
21|    if (!storage) return null;
22|    const raw = storage.getItem(MUSIC_PREFS_KEY);
23|    if (!raw) return null;
24|    const json: unknown = JSON.parse(raw);
25|    if (typeof json !== "object" || json === null) return null;
26|    const { style, volume, muted, playlist } = json as Record<string, unknown>;
27|    return {
28|      style: typeof style === "string" ? style : null,
29|      volume: validVolume(volume),
30|      muted: typeof muted === "boolean" ? muted : false,
31|      playlist: typeof playlist === "boolean" ? playlist : false,
32|    };
33|  } catch {
34|    return null;
35|  }
36|}
37|
38|function writeStored(storage: PrefsStorage | undefined, prefs: PersistedMusicPrefs): void {
39|  try {
40|    storage?.setItem(MUSIC_PREFS_KEY, JSON.stringify(prefs));
41|  } catch {
42|    // Private mode: playback continues without persistence.
43|  }
44|}
45|
46|function defaultStorage(): PrefsStorage | undefined {
47|  try {
48|    if (typeof window === "undefined") return undefined;
49|    return window.localStorage;
50|  } catch {
51|    return undefined;
52|  }
53|}
54|
55|export function loadMusicPrefs(): PersistedMusicPrefs | null {
56|  return readStored(defaultStorage());
57|}
58|
59|// The one owner of the persisted prefs: load caches the full object and
60|// every partial update merges over it, so a volume or mute change before
61|// the manifest loads never clobbers the stored style or Chopin mode.
62|export function createMusicPrefsStore(storage: PrefsStorage | undefined = defaultStorage()) {
63|  let current: PersistedMusicPrefs | null = null;
64|  let loaded = false;
65|
66|  function load(): PersistedMusicPrefs | null {
67|    if (!loaded) {
68|      current = readStored(storage);
69|      loaded = true;
70|    }
71|    return current;
72|  }
73|
74|  function update(patch: Partial<PersistedMusicPrefs>): PersistedMusicPrefs {
75|    const base: PersistedMusicPrefs = load() ?? {
76|      style: null,
77|      volume: DEFAULT_VOLUME,
78|      muted: false,
79|      playlist: false,
80|    };
81|    current = { ...base, ...patch };
82|    writeStored(storage, current);
83|    return current;
84|  }
85|
86|  return { load, update };
